   <label><span>Kişisel PIN</span><div className="account-input-wrap has-toggle"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 118 0v3"/></svg><input autoComplete={registering?'new-password':'current-password'} type={showPin?'text':'password'} inputMode="numeric" maxLength={12} value={authPin} onChange={event=>setAuthPin(event.target.value.replace(/\D/g,'').slice(0,12))} placeholder="6–12 rakam" required/>{pinToggle(showPin,setShowPin,'PIN')}</div></label>
