function RoundSummary({room,playerId,onClose,onPoints,onNext,onNewGame,isOwner}:{room:PublicRoom;playerId:string;onClose:()=>void;onPoints:()=>void;onNext:()=>void;onNewGame:()=>void;isOwner:boolean}){
 const finalRound=room.status==='match-end'||room.round>=room.settings.rounds;
 const roundPoints=(id:string)=>room.roundScores.find(entry=>entry.round===room.round&&entry.playerId===id)?.points||0;
 const rankedPlayers=rankPlayersByTotal(room.players);
 const teams=room.settings.mode==='pairs'?calculateTeamScoreboard(room.players,room.roundScores,room.round):[];
 const currentTeam=teams.find(team=>team.playerIds.includes(playerId));
 const currentPlace=finalRound&&room.settings.mode==='pairs'?(currentTeam?.overallRank||0):playerTotalRank(room.players,playerId);
 const currentStats=room.matchStats[playerId]||{bestScore:0,seriesOpens:0,pairOpens:0,penaltyCount:0,penaltyPoints:0};
 const roundPenaltyPoints=(id:string)=>room.roundPenaltyTotals?.[id]??room.penaltyHistory.filter(entry=>entry.round===room.round&&entry.playerId===id).reduce((total,entry)=>total+entry.points,0);
 const [secondsLeft,setSecondsLeft]=useState(finalRound?60:15);
 useEffect(()=>{if(typeof room.roundAutoStartAt!=='number')return;const restartAt=room.roundAutoStartAt,serverOffset=room.serverNow-Date.now();const update=()=>setSecondsLeft(Math.max(0,Math.ceil((restartAt-(Date.now()+serverOffset))/1000)));update();const timer=window.setInterval(update,250);return()=>window.clearInterval(timer)},[room.roundAutoStartAt,room.serverNow]);
 const renderTeamRows=()=>teams.map(team=>{const members=team.playerIds.map(id=>room.players.find(player=>player.id===id)).filter((player):player is PublicRoom['players'][number]=>!!player),penalizedMembers=members.filter(player=>roundPenaltyPoints(player.id)>0);return <tr key={team.teamId} className={team.playerIds.includes(playerId)?'score-leading':''}><td>{team.overallRank}.</td><td>{members.map(player=>player.name).join(' + ')}</td><td>{team.roundPoints}</td>{finalRound&&<td>{penalizedMembers.length?penalizedMembers.map(player=><em key={player.id} className="score-penalty">{player.name} +{roundPenaltyPoints(player.id)}</em>):'—'}</td>}<td>{team.previousTotal}</td><td><b>{team.total}</b></td>{!finalRound&&<td>{team.roundRank}.</td>}</tr>});
 return <EuiModal onClose={onClose} className={`round-modal${finalRound?' round-modal-final':''}`}><EuiModalHeader className="round-modal-head"><EuiModalHeaderTitle><span>{finalRound?room.settings.mode==='pairs'?`Oyun bitti, takımın ${currentPlace}. oldu!`:`Oyun bitti${currentPlace>0?`, ${currentPlace}. oldun`:''}!`:`${room.round}. el bitti`}</span></EuiModalHeaderTitle>{finalRound?<div className="next-round">{typeof room.roundAutoStartAt==='number'?<>Lobiye dönülüyor... <span className="countdown">{secondsLeft}</span></>:'Yeni maç için ayarları seçin'}</div>:<div className="next-round">{room.round+1}. el başlıyor... <span className="countdown">{secondsLeft}</span></div>}</EuiModalHeader><EuiModalBody className="round-summary-body">
  <div className={`round-summary-layout${finalRound?' is-final':''}`}>
   {finalRound&&room.settings.mode==='pairs'?<section className="round-summary-teams is-final-teams"><h3>Takım sıralaması</h3><table className="score-table"><thead><tr><th>SIRA</th><th>TAKIM</th><th>SON EL</th><th>SON EL CEZALARI</th><th>ÖNCEKİ TOPLAM</th><th>GENEL TOPLAM</th></tr></thead><tbody>{renderTeamRows()}</tbody></table></section>:<section className="round-summary-players"><table className="score-table"><thead><tr><th>SIRA</th><th>OYUNCU</th><th>TOPLAM</th><th>{room.round}. EL</th>{finalRound&&<th>SON EL ROZETİ</th>}</tr></thead><tbody>{rankedPlayers.map(player=>{const badge=finalRound?room.matchBadges.find(entry=>entry.round===room.round&&entry.playerId===player.id):undefined,penalty=roundPenaltyPoints(player.id),rank=playerTotalRank(room.players,player.id);return <tr key={player.id} className={player.id===playerId?'score-leading':''}><td>{rank}.</td><td><div className="score-player"><EuiAvatar name={player.name} initials={player.avatar} size="m"/><span>{player.name}</span></div></td><td><b>{player.score}</b></td><td>{roundPoints(player.id)}{penalty>0&&<em className="score-penalty">+{penalty}</em>}</td>{finalRound&&<td>{badge&&<span title={`${badge.round}. elde ${matchBadgeDescription(badge.place)}`} aria-label={`${badge.round}. elde ${matchBadgeDescription(badge.place)}`}>{matchBadgeIcon(badge.place)}</span>}</td>}</tr>})}</tbody></table></section>}
   {finalRound&&<aside className="match-summary-stats" aria-label="Maç istatistikleri"><div><span>En iyi skor</span><b>{currentStats.bestScore}</b></div><div><span>Düz açma</span><b>{currentStats.seriesOpens}x</b></div><div><span>Çift açma</span><b>{currentStats.pairOpens}x</b></div><div><span>Cezalar</span><b>{currentStats.penaltyCount}x</b></div></aside>}
   {!finalRound&&teams.length>0&&<section className="round-summary-teams"><h3>Takım sıralaması</h3><table className="score-table"><thead><tr><th>GENEL SIRA</th><th>TAKIM</th><th>BU TUR</th><th>ÖNCEKİ TOPLAM</th><th>GENEL TOPLAM</th><th>EL SIRASI</th></tr></thead><tbody>{renderTeamRows()}</tbody></table></section>}
  </div>
 </EuiModalBody><EuiModalFooter className="round-modal-footer"><EuiButton className="points-button" onClick={onPoints}>Puan Durumu</EuiButton>{isOwner&&room.status==='round-end'&&!finalRound&&<EuiButton className="round-next" fill onClick={onNext}>Sonraki el</EuiButton>}{isOwner&&room.status==='match-end'&&<EuiButton className="round-close round-new-game" fill onClick={onNewGame}>YENİ OYUN</EuiButton>}<EuiButton className="round-close" fill onClick={onClose}>Kapat</EuiButton></EuiModalFooter></EuiModal>
}
